class Solution {
public:
   string decodeString(const string &s) {
    stack<string> strStack;
    stack<int> numStack;
    string currentStr = "";
    int currentNum = 0;

    for (char c : s) {
        if (isdigit(c)) {
            // Build the number
            currentNum = currentNum * 10 + (c - '0');
        } else if (c == '[') {
            // Push the current string and number onto their respective stacks
            strStack.push(currentStr);
            numStack.push(currentNum);

            // Reset current string and number
            currentStr = "";
            currentNum = 0;
        } else if (c == ']') {
            // Pop from the stacks
            string tempStr = currentStr;
            int repeatCount = numStack.top();
            numStack.pop();
            currentStr = strStack.top();
            strStack.pop();

            // Repeat the string and append it
            while (repeatCount-- > 0) {
                currentStr += tempStr;
            }
        } else {
            // Append current character to the current string
            currentStr += c;
        }
    }

    return currentStr;
}
};
